EXEC sp_addextendedproperty @name=N'MS_Description', @value=N'Number of queued chunks the run was split into. The run is ended when this many Communication Run Chunks have been recorded. NULL for a run that is not chunked.', @level0type=N'SCHEMA', @level0name=N'${flyway:defaultSchema}', @level1type=N'TABLE', @level1name=N'CommunicationRun', @level2type=N'COLUMN', @level2name=N'ChunkCount';
